function Plot_EOCombinationCandidateComparison()
%PLOT_EOCOMBINATIONCANDIDATECOMPARISON Plot pair-specific optimum gaps.
root=fileparts(mfilename('fullpath'));outDir=fullfile(root,'output','eo_combination_order_diagnostic');T=readtable(fullfile(outDir,'candidate_pair_comparison.csv'));pairs=unique(T{:,{'eo1','eo2'}},'rows','stable');labels={'Noiseless','25','15','5'};fig=figure('Color','w','Units','centimeters','Position',[2 2 12 8]);hold on;box on;cc=lines(size(pairs,1));for i=1:size(pairs,1),idx=T.eo1==pairs(i,1)&T.eo2==pairs(i,2);[~,o]=sort(T.snr_index(idx));q=find(idx);q=q(o);plot(1:4,1000*T.rmse_excess_V(q),'-o','LineWidth',1.2,'MarkerSize',5,'Color',cc(i,:),'DisplayName',sprintf('(%d,%d)',pairs(i,1),pairs(i,2)));end;set(gca,'XTick',1:4,'XTickLabel',labels,'TickDir','in','FontName','Times New Roman','FontSize',9);xlabel('Common low/high SNR (dB)');ylabel('Pair-specific RMSE excess above best (mV)');legend('Location','best');exportgraphics(fig,fullfile(outDir,'candidate_pair_rmse_comparison.png'),'Resolution',240);try,exportgraphics(fig,fullfile(outDir,'candidate_pair_rmse_comparison.pdf'),'ContentType','vector');catch,end
end
